88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        if (this.clinicService.isTelephoneInUse(owner.getTelephone())) {
108	            return new ResponseEntity<>(HttpStatus.CONFLICT);
109	        }
110	        // Per-city capacity: a city that already holds the maximum number of owners is full.
111	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
112	            return new ResponseEntity<>(HttpStatus.CONFLICT);
113	        }
114	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
115	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress());
116	        if (householdInUse) {
117	            if (!sharesHousehold) {
118	                return new ResponseEntity<>(HttpStatus.CONFLICT);
119	            }
120	            // Joining an existing household: assign the shared, stable household identifier to
121	            // the new owner (and back-fill the existing member(s)).
122	            this.clinicService.assignHousehold(owner);
123	        }
124	        owner.setNamesakeCount(
125	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        headers.setLocation(UriComponentsBuilder.newInstance()
129	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
